export type ServedView = { "basis": { "revision": number; "through_seq": number; }; "document": { "revision": number; "projection": ServedProjection; }; "thread": { "projection": ServedProjection; "threads": ReadonlyArray<ServedThread>; }; "obligations": ReadonlyArray<ServedObligation>; "reports": ReadonlyArray<{ "id": string; "target": { "kind": "widget"; "id": string; }; "source": "report"; "action": string; "detail": { [key: string]: unknown; }; "text": string | null; "ts": string; "revision": number; "seq": number; "agent": string | null; "session": string | null; "disposition": "effective" | "outranked" | "settled"; }>; "undo": ReadonlyArray<{ "event": ServedEvent; "coordinate"?: ReadonlyArray<string>; "newest"?: true; "gesture"?: ServedGesture; "picked_up"?: true; }>; "coverage": ReadonlyArray<{ "event": ServedEvent; "coordinate": ReadonlyArray<string> | null; }>; "published_at": string | null; "queues": { "on_user": ReadonlyArray<ServedQueueRow>; "on_agent": ReadonlyArray<ServedQueueRow>; "done": ReadonlyArray<ServedDoneRow>; }; };
export type ServedProjection = { "entries": ReadonlyArray<{ "event": EventMap["action"] | EventMap["report"]; "coordinate": readonly [string, string, string]; "spec": ServedVerb; "value": unknown; "scope": "document" | "thread"; "restated": ReadonlyArray<string>; "absorbed": boolean; "stands": boolean; }>; "actions": ReadonlyArray<string>; "reports": ReadonlyArray<string>; "desired": ReadonlyArray<string>; };
export type ServedObligation = { "id": string; "source": { "kind": "widget"; "id": string; "tag": string; "unit"?: string; } | { "kind": "update"; "id": string; "subject": ServedSubject; } | { "kind": "message"; "id": string; } | { "kind": "todo"; "id": string; "subject": ServedSubject; }; "thread": string | null; "message": string | null; "prompt": { "text": string | null; "target": string | null; }; "answer": { "value": unknown; "event": ServedEventReference | null; } | null; "status": "open" | "answered" | "answered_elsewhere" | "withdrawn"; "end": { "detail": string | null; "event": { "id": string; "seq": number; "ts": string; "author": string; }; } | null; "next_actor": "user" | "agent" | null; };
export type ServedQueueRow = ServedObligationRow | ServedTodoRow;
export type ServedObligationRow = { "kind": "widget" | "update" | "message" | "todo"; "id": string; "owner": "user" | "agent"; "subject": ServedSubject; "thread": string | null; "also": ReadonlyArray<string>; "live": boolean; };
export type ServedTodoRow = { "kind": "todo"; "id": string; "owner": "agent"; "subject": ServedSubject; "thread": string | null; "live": boolean; };
export type ServedDoneRow = ServedObligationRow & { "state": "done" | "failed" | "dropped"; "ended": string | null; "detail": string | null; } | ServedTodoRow & { "state": "done" | "failed" | "dropped"; "ended": string | null; "detail": string | null; };
export type ServedAnchor = Exclude<EventMap["comment"]["anchor"], undefined> | Exclude<EventMap["reply"]["anchor"], undefined> | Exclude<EventMap["reanchor"]["anchor"], undefined>;
export type ServedMessage = EventMap["comment"] & { "agent"?: string; "key"?: string; "content_version": string; "completed_by"?: string; "edited"?: { "id": string; "seq": number; "ts": string; "was": string; }; } | EventMap["reply"] & { "agent"?: string; "key"?: string; "content_version": string; "completed_by"?: string; "edited"?: { "id": string; "seq": number; "ts": string; "was": string; }; } | { "id": string; "content_version": string; "attempt": string; "key": string; "provisional": true; "kind": "reply"; "addressable": false; "author": "agent"; "agent": string | null; "parent": string; "text": string; "ts": string; "pending": boolean; };
export type ServedContentVersion = { "message": string; "version": string; };
export type ServedAttention = { "kind": "needs_user"; "reason": "obligation" | "resend"; "workflow": string | null; } | { "kind": "waiting"; "reason": "uncertain" | "workflow"; "workflow": string; } | { "kind": "waiting"; "reason": "todo"; "workflow": null; "todo": string; } | null;
export type ServedThread = { "id": string; "root": ServedMessage; "title": string | null; "anchor": ServedAnchor; "detached_from": ServedAnchor; "rewritten_from": ServedAnchor; "msgs": ReadonlyArray<ServedMessage>; "revisions": ReadonlyArray<EventMap["edit"] & { "was": string; }>; "resolved": EventMap["resolve"] & { "agent"?: string; } | EventMap["action"] & { "agent"?: string; } | null; "bare_reaction": boolean; "seat": string | null; "summaries": ReadonlyArray<{ "id": string; "seq": number; "from": string; "through": string; "covers": ReadonlyArray<string>; "text": string; "label": string; "protected": ReadonlyArray<string>; }>; "unread": ReadonlyArray<ServedContentVersion>; "attention": ServedAttention; };
export type ServedStage = "sent" | "queued" | "picked_up" | "working" | "replying" | "answered";
export type ServedViewAnswer = { "browser": ServedBrowser; };
export type ServedEventAnswer = { "ok": true; "state": ServedState; } | { "ok": false; "final": true; "error": string; "findings": ReadonlyArray<ServedFinding>; "attempt"?: unknown; "state"?: ServedState; } | { "ok": false; "error": string; "attempt"?: unknown; };
export type ServedFinding = { "code": string; "severity": "error" | "advice"; "at"?: string; "values"?: { [key: string]: unknown; }; };
export type ServedSampleAnswer = { "url": string; "page": string; };
export type ServedMediaAnswer = { "path": string; };
export type ServedFileSnapshot = { "label": string; "text": string; "revision": string; };
export type ServedStaleFile = { "error": string; "current": ServedFileSnapshot; };
export type ServedRefusal = { "error": string; };
export type ServedLayerAnswer = { "layer": string; };
export type ServedVerb = { "detail"?: { "type": "object"; "properties"?: unknown; "required"?: unknown; "additionalProperties": false; }; "unit": string; "record"?: { "kind": "attribute"; "attr": string; } | { "kind": "position"; "within": string; } | { "kind": "body"; } | { "kind": "value"; "attr": string; }; "writer"?: "agent"; "attention"?: true; "creates"?: { "child": string; "words": string; }; "decides"?: true; "contract"?: { "field": string; "attribute": string; }; "text"?: true; };
export type ServedState = ServedReading & { "others": ReadonlyArray<{ "page_key": string; "url": string; "title": string; "session_cwd": string | null; "activity": { [key: string]: unknown; }; }>; "reading": string; "leaf"?: ServedProvenance; "release"?: string; };
